PREFERENCIA_DRIVERS = ["ODBC Driver 18 for SQL Server", "ODBC Driver 17 for SQL Server",
                       "ODBC Driver 13 for SQL Server"]
ES_WINDOWS = os.name == "nt"


class ErrorInstalador(Exception):
    pass


# --------------------------------------------------------------------------- utilidades
def hablar(msg=""):
    print(msg, flush=True)


def paso(n, total, titulo):
    hablar(f"\n[{n}/{total}] {titulo}")


def ok(msg):
    hablar(f"      [OK] {msg}")


def aviso(msg):
    hablar(f"      [!]  {msg}")


def interactivo():
    try:
        return sys.stdin is not None and sys.stdin.isatty()
    except Exception:
        return False


def preguntar(texto, secreto=False, defecto=""):
    if not interactivo():
        return defecto
    try:
        v = getpass.getpass("      " + texto) if secreto else input("      " + texto)
    except (EOFError, KeyboardInterrupt):
        return defecto
    return v.strip() if v.strip() else defecto


def si_no(texto, defecto=True):
    if not interactivo():
        return defecto
    r = preguntar(texto + (" [S/n]: " if defecto else " [s/N]: "))
    return defecto if not r else r.lower().startswith(("s", "y"))


def python_del_entorno(destino):
    sub = ("Scripts", "python.exe") if ES_WINDOWS else ("bin", "python")
    return destino / ".venv" / sub[0] / sub[1]


def ejecutar(cmd, cwd=None, env=None):
    r = subprocess.run(cmd, cwd=cwd, env=env, capture_output=True, text=True)
    return r.returncode, (r.stdout or "") + (r.stderr or "")


def cola(texto, n=12):
    return "\n".join("        " + l for l in texto.strip().splitlines()[-n:])


def comillas(v):
    """Valor seguro para un archivo .env (claves con #, espacios o comillas)."""
    if re.search(r"[\s#\"'\\$]", v):
        return '"' + v.replace("\\", "\\\\").replace('"', '\\"') + '"'
    return v


def leer_env(ruta):
    d = {}
    if ruta.exists():
        for l in ruta.read_text(encoding="utf-8").splitlines():
            if "=" in l and not l.lstrip().startswith("#"):
                k, v = l.split("=", 1)
                d[k.strip()] = v.strip().strip('"')
    return d


def poner_env(ruta, **kv):
    lineas = ruta.read_text(encoding="utf-8").splitlines() if ruta.exists() else []
    hechos = set()
    for i, l in enumerate(lineas):
        k = l.split("=", 1)[0].strip()
        if "=" in l and not l.lstrip().startswith("#") and k in kv:
            lineas[i] = f"{k}={comillas(str(kv[k]))}" if kv[k] != "" else f"{k}="
            hechos.add(k)
    for k, v in kv.items():
        if k not in hechos:
            lineas.append(f"{k}={comillas(str(v))}" if v != "" else f"{k}=")
    ruta.write_text("\n".join(lineas) + "\n", encoding="utf-8")


def elegir_driver(instalados):
    for d in PREFERENCIA_DRIVERS:
        if d in instalados:
            return d
    return None


# --------------------------------------------------------------------------- pasos
def revisar_python():
    v = sys.version_info
    if v < (3, 9):
        raise ErrorInstalador(f"Tu Python es {v.major}.{v.minor}. Se necesita 3.9 o superior "
                              "(recomendado 3.11 o 3.12). Descargalo desde python.org.")
    ok(f"Python {v.major}.{v.minor}.{v.micro}")


def cargar_paquete():
    try:
        raw = zlib.decompress(base64.b64decode("".join(PAQUETE.split())))
    except Exception as e:
        raise ErrorInstalador("El instalador esta danado (no se pudo descomprimir). "
                              "Vuelve a descargarlo y ejecutalo sin abrirlo ni editarlo.") from e
    if hashlib.sha256(raw).hexdigest() != SHA256:
        raise ErrorInstalador("El instalador esta danado (la descarga se corto o el archivo "
                              "fue modificado). Vuelve a descargarlo.")
    return json.loads(raw.decode("utf-8"))


def copiar_archivos(destino, archivos):
    destino.mkdir(parents=True, exist_ok=True)
    nuevos = cambiados = iguales = 0
    for ruta, cont in archivos.items():
        dst = destino / ruta
        if dst.name == ".env":
            continue  # nunca se pisan las credenciales
        dst.parent.mkdir(parents=True, exist_ok=True)
        binario = isinstance(cont, dict)  # fuentes e imagenes viajan en base64
        datos = base64.b64decode(cont["b64"]) if binario else None
        if dst.exists():
            if binario:
                igual = dst.read_bytes() == datos
            else:
                igual = dst.read_text(encoding="utf-8", errors="replace").replace("\r\n", "\n") == cont
            if igual:
                iguales += 1
                continue
            cambiados += 1
        else:
            nuevos += 1
        if binario:
            dst.write_bytes(datos)
        elif ruta.startswith("public/vendor/"):
            dst.write_bytes(cont.encode("utf-8"))  # librerias minificadas: tal cual, sin cambiar saltos de linea
        else:
            dst.write_text(cont, encoding="utf-8")
    ok(f"{nuevos} archivos nuevos, {cambiados} actualizados, {iguales} sin cambios")
    ok(f"Carpeta: {destino}")


def crear_entorno(destino):
    py = python_del_entorno(destino)
    if py.exists():
        ok("Entorno ya existia, se reutiliza")
        return py
    hablar("      Creando entorno aislado (una sola vez)...")
    try:
        venv.EnvBuilder(with_pip=True, clear=False).create(str(destino / ".venv"))
    except Exception as e:
        raise ErrorInstalador(f"No se pudo crear el entorno: {e}") from e
    if not py.exists():
        raise ErrorInstalador("El entorno se creo incompleto. Borra la carpeta .venv e intenta de nuevo.")
    ok("Entorno creado")
    return py


def instalar_librerias(destino, py):
    req = destino / "requirements.txt"
    base = [l.strip() for l in req.read_text(encoding="utf-8").splitlines()
            if l.strip() and not l.strip().startswith("#")]
    nucleo = [l for l in base if not l.lower().startswith("pyodbc")]
    hablar("      Instalando librerias (la primera vez puede tardar unos minutos)...")
    code, out = ejecutar([str(py), "-m", "pip", "install", "-q", "--disable-pip-version-check"] + nucleo)
    if code != 0:
        raise ErrorInstalador("No se pudieron instalar las librerias. Revisa tu conexion a internet "
                              "o el proxy de la empresa y vuelve a ejecutar el instalador.\n" + cola(out))
    ok("Librerias principales listas")
    code, out = ejecutar([str(py), "-m", "pip", "install", "-q", "--disable-pip-version-check", "pyodbc>=5.1"])
    if code != 0:
        aviso("No se pudo instalar pyodbc (necesario solo para conectar a SQL Server).")
        aviso("El modo DEMO funciona igual. Avisa a quien te apoye con esto:")
        hablar(cola(out, 4))
    else:
        c2, o2 = ejecutar([str(py), "-c", "import pyodbc"])
        if c2 == 0:
            ok("pyodbc listo (conexion a SQL Server)")
        else:
            aviso("pyodbc se instalo pero no se puede cargar (falta el componente ODBC del sistema).")
            aviso("En Windows esto no deberia pasar. El modo DEMO funciona igual.")


def drivers_instalados(py):
    code, out = ejecutar([str(py), "-c", "import pyodbc,json;print(json.dumps(pyodbc.drivers()))"])
    if code != 0:
        return None
    try:
        return json.loads(out.strip().splitlines()[-1])
    except Exception:
        return None


def configurar(destino, py, forzar_demo):
    env = destino / ".env"
    primera = not env.exists()
    if primera:
        base = destino / ".env.example"
        env.write_text(base.read_text(encoding="utf-8") if base.exists() else "", encoding="utf-8")

    # --- driver ODBC: usar el que realmente tienes instalado
    lista = drivers_instalados(py)
    if lista is None:
        aviso("Driver ODBC: no se pudo revisar (pyodbc no carga). Solo afecta a los datos reales.")
    else:
        actual = leer_env(env).get("ODBC_DRIVER", "")
        mejor = elegir_driver(lista)
        if mejor is None:
            aviso("No hay 'ODBC Driver for SQL Server' instalado en este computador.")
            aviso("Para datos reales instala 'Microsoft ODBC Driver 18 for SQL Server' (msodbcsql.msi,")
            aviso("descarga gratuita de Microsoft). Para el modo DEMO no hace falta.")
        elif actual not in lista:
            poner_env(env, ODBC_DRIVER=mejor)
            ok(f"Driver ODBC detectado y configurado: {mejor}")
        else:
            ok(f"Driver ODBC correcto: {actual}")

    # --- credenciales: solo la primera vez
    if not primera:
        ok("Se conserva tu archivo .env (credenciales sin cambios)")
        return
    datos = {}
    if not forzar_demo and interactivo():
        hablar("\n      Conexion a las bases de datos (Enter para omitir cualquier dato)")
        hablar("      Azure / VTEX  (Alfred-Cloud, exige usuario y clave de SQL)")
        datos["VTEX_USER"] = preguntar("  Usuario Azure : ")
        if datos["VTEX_USER"]:
            datos["VTEX_PASS"] = preguntar("  Clave Azure   : ", secreto=True)
        hablar("      ODS / SAP  (clws0156). Si entras con tu cuenta de Windows, deja el usuario vacio.")
        datos["SAP_USER"] = preguntar("  Usuario ODS   : ")
        if datos["SAP_USER"]:
            datos["SAP_PASS"] = preguntar("  Clave ODS     : ", secreto=True)
    if forzar_demo or not datos.get("VTEX_USER"):
        datos["DEMO"] = "1"
        aviso("Sin credenciales de Azure: queda en MODO DEMO (datos de ejemplo, con etiqueta visible).")
        aviso("Para usar datos reales: abre el archivo .env, completa los usuarios y borra el 1 de DEMO=1.")
    poner_env(env, **datos)
    ok("Archivo .env creado")


def probar(destino, py):
    code_py = ("from app import servicio; p=servicio.obtener({}); "
               "print(p['kpi']['pedidos'], len(p['detalle']))")
    envv = dict(os.environ, DEMO="1")
    t0 = time.time()
    code, out = ejecutar([str(py), "-c", code_py], cwd=str(destino), env=envv)
    if code != 0:
        raise ErrorInstalador("La prueba automatica fallo. Detalle:\n" + cola(out))
    ok(f"Prueba automatica superada ({time.time() - t0:.0f} s): el motor de calculo funciona")


def puerto_libre(inicio=8000):
    for p in range(inicio, inicio + 11):
        with socket.socket() as s:
            if s.connect_ex(("127.0.0.1", p)) != 0:
                return p
    raise ErrorInstalador("No hay un puerto libre entre 8000 y 8010. Cierra otros programas.")


def iniciar(destino, py):
    puerto = puerto_libre()
    url = f"http://127.0.0.1:{puerto}"
    hablar(f"\n  Iniciando en {url}")
    hablar("  NO cierres esta ventana mientras uses el dashboard (cerrarla lo apaga).")
    hablar("  Para volver a abrirlo otro dia: doble clic en run.bat dentro de la carpeta.")
    hablar("  Para publicarlo en la red de la empresa: servidor.bat.\n")
    proc = subprocess.Popen([str(py), "-m", "uvicorn", "app.main:app", "--host", "127.0.0.1",
                             "--port", str(puerto)], cwd=str(destino))
    for _ in range(60):
        if proc.poll() is not None:
            raise ErrorInstalador("El servidor se detuvo al iniciar. Ejecuta run.bat para ver el detalle.")
        try:
            urllib.request.urlopen(url + "/api/config", timeout=2)
            break
        except Exception:
            time.sleep(0.5)
    try:
        webbrowser.open(url)
    except Exception:
        pass
    try:
        proc.wait()
    except KeyboardInterrupt:
        proc.terminate()
        hablar("\n  Dashboard detenido.")


# --------------------------------------------------------------------------- principal
def main():
    ap = argparse.ArgumentParser(add_help=True)
    ap.add_argument("--demo", action="store_true")
    ap.add_argument("--run", action="store_true")
    ap.add_argument("--no-run", action="store_true")
    ap.add_argument("--no-pip", action="store_true", help=argparse.SUPPRESS)
    ap.add_argument("--carpeta", default=os.environ.get("DASHBOARD_D2C_DIR", ""))
    a = ap.parse_args()
    destino = Path(a.carpeta) if a.carpeta else Path.home() / "dashboard-d2c"

    try:
        sys.stdout.reconfigure(encoding="utf-8", errors="replace")
    except Exception:
        pass
    hablar("=" * 64)
    hablar(f"  {NOMBRE}  |  Instalador v{VERSION}")
    hablar("=" * 64)
    actualizacion = (destino / "app" / "main.py").exists()
    hablar("  Modo: " + ("ACTUALIZACION (tu .env se conserva)" if actualizacion else "INSTALACION NUEVA"))
    total = 6

    paso(1, total, "Revisando Python")
    revisar_python()
    paso(2, total, "Copiando el proyecto")
    copiar_archivos(destino, cargar_paquete())
    paso(3, total, "Preparando el entorno")
    py = crear_entorno(destino)
    paso(4, total, "Instalando librerias")
    if a.no_pip:
        aviso("Omitido (--no-pip)")
    else:
        instalar_librerias(destino, py)
    paso(5, total, "Configurando la conexion")
    configurar(destino, py, a.demo)
    paso(6, total, "Prueba automatica")
    probar(destino, py)

    hablar("\n" + "=" * 64)
    hablar("  INSTALACION COMPLETA")
    hablar("=" * 64)
    hablar(f"  Carpeta: {destino}")
    hablar("  Para que OTROS PCs de la red entren desde su navegador (sin instalar nada):")
    hablar("  deja este equipo encendido y haz doble clic en servidor.bat; muestra la direccion para compartir.")
    quiere = a.run or (not a.no_run and si_no("\n  Iniciar el dashboard ahora?", True))
    if quiere:
        iniciar(destino, py)
    elif interactivo():
        input("\n  Presiona Enter para cerrar...")


if __name__ == "__main__":
    try:
        main()
    except ErrorInstalador as e:
        print("\n  [ERROR] " + str(e), flush=True)
        if interactivo():
            try:
                input("\n  Presiona Enter para cerrar...")
            except Exception:
                pass
        sys.exit(1)
    except KeyboardInterrupt:
        print("\n  Cancelado.")
        sys.exit(130)